for wb in xl.Workbooks:
    print('WB:',wb.Name)
    for sh in wb.Sheets:
        ur=sh.UsedRange
        print('  sheet:',sh.Name,'rows',ur.Rows.Count,'cols',ur.Columns.Count,'addr',ur.Address)
